pub(crate) static ooxmlShapeName: &[&str] = &["snip1Rect", "snip2SameRect", "snip2DiagRect", "snipRoundRect", "round1Rect", "round2SameRect", "round2DiagRect", "heptagon", "pie", "chord", "teardrop", "halfFrame", "corner", "diagStripe", "cloud", "mathPlus", "mathMinus", "mathMultiply", "mathDivide", "mathEqual", "mathNotEqual", "star6", "star7", "star10", "star12", "decagon", "dodecagon", "frame", "arc", "trapezoid", "heart"];
